using System;
using System.Collections.Generic;
using System.Xml.Serialization;
namespace Downfield {
public partial class Franchise {
 [XmlIgnore]public string PersonnelNotice="";
 public void EnsureJerseyNumbers(){for(int team=0;team<Teams.Count;team++){HashSet<int> used=new HashSet<int>();List<ClubPlayer> squad=Squad(team);squad.Sort((a,b)=>(a.Slot<0?1:0).CompareTo(b.Slot<0?1:0));foreach(ClubPlayer player in squad){if(player.Number<0||player.Number>99||used.Contains(player.Number)){int number=player.Number<0?1:player.Number%100;for(int tries=0;tries<100&&used.Contains(number);tries++)number=(number+1)%100;player.Number=number;}used.Add(player.Number);}}}
 public void DressActualRoster(List<Player> field){EnsureJerseyNumbers();PersonnelNotice="";HashSet<int> used=new HashSet<int>();for(int slot=0;slot<field.Count;slot++){Player actor=field[slot];int team=slot<11?UserTeam:ActiveOpponent;ClubPlayer starter=Starter(team,slot),player=starter;if(player==null||player.InjuryWeeks>0||used.Contains(player.Id)){List<ClubPlayer> reserves=Players.FindAll(p=>p.Team==team&&p.Role==Roles[slot]&&p.Slot<0&&p.InjuryWeeks==0&&!used.Contains(p.Id));reserves.Sort((a,b)=>b.OVR.CompareTo(a.OVR));player=reserves.Count>0?reserves[0]:null;}actor.Primary=Palette[Teams[team].Primary];actor.Secondary=Palette[Teams[team].Secondary];if(player==null){actor.Active=false;actor.HasBall=false;actor.ClubId=-1;actor.Name="";actor.Number=0;actor.Speed=0;actor.VX=actor.VZ=0;if(slot<11&&PersonnelNotice.Length==0)PersonnelNotice="NO HEALTHY "+Roles[slot]+" / SPOT EMPTY";continue;}used.Add(player.Id);actor.Active=true;actor.ClubId=player.Id;actor.Name=player.Name;actor.Number=player.Number;actor.OVR=player.OVR;actor.Hands=player.Hands;actor.Power=player.Power;actor.Speed=Simulation.SkillSpeed(actor.Role,player.Speed);if(slot<11&&starter!=null&&starter.Id!=player.Id&&PersonnelNotice.Length==0)PersonnelNotice="#"+starter.Number+" OUT / #"+player.Number+" "+player.Name+" IN";}}
}
public partial class Simulation {
 public string PersonnelNotice="";public bool Wildcat;public int OnFieldCount(int team){return Players.FindAll(p=>p.Team==team&&p.Active).Count;}
 void PreparePersonnel(){Wildcat=false;PersonnelNotice=Franchise==null?"":Franchise.PersonnelNotice;if(Players[0].Active){Controlled=Players[0];Controlled.HasBall=true;return;}Player replacement=Players.Find(p=>p.Team==0&&p.Active&&p.Role!="OL")??Players.Find(p=>p.Team==0&&p.Active);if(replacement==null){State=Phase.GameOver;AwayScore=Math.Max(AwayScore,HomeScore+1);Message="NO HEALTHY OFFENSE / FORFEIT";return;}Player qb=Players[0];qb.Active=true;qb.ClubId=replacement.ClubId;qb.Name=replacement.Name;qb.Number=replacement.Number;qb.Primary=replacement.Primary;qb.Secondary=replacement.Secondary;qb.OVR=replacement.OVR;qb.Hands=replacement.Hands;qb.Power=replacement.Power;qb.Speed=replacement.Speed;replacement.Active=false;replacement.HasBall=false;Controlled=qb;qb.HasBall=true;Wildcat=true;PersonnelNotice="WILDCAT / #"+qb.Number+" "+qb.Name+" AT QB";}
}
}
